      var a = document.createElement("a");
      a.className = "post reveal in";
      a.href = cleanLink(it.link);
      a.target = "_blank";
      a.rel = "noopener";
      if (i % 3 === 1) a.setAttribute("data-delay", "1");
      if (i % 3 === 2) a.setAttribute("data-delay", "2");
      var src = firstImage(it);
      if (src) {
        a.classList.add("has-thumb");
        var thumb = document.createElement("div");
        thumb.className = "post-thumb";
        var im = document.createElement("img");
        im.loading = "lazy";
        im.alt = "";
        im.src = src;
        im.onerror = function () {
          a.classList.remove("has-thumb");
          if (thumb.parentNode) thumb.parentNode.removeChild(thumb);
        };
        thumb.appendChild(im);
        a.appendChild(thumb);
      }
      var date = document.createElement("span");
      date.className = "date";
      date.textContent = fmtDate(it.pubDate);
      var h = document.createElement("h3");
      h.textContent = decode(it.title);
      var more = document.createElement("span");
      more.className = "more";
      more.textContent = window.__t ? window.__t("Read on Medium →") : "Read on Medium →";
      a.appendChild(date);
      a.appendChild(h);
      a.appendChild(more);
      frag.appendChild(a);
